//! Audit shims — packet-08 (RED).
//!
//! Trait-шов McpProbe + заглушки; реальный rmcp spawn — packet-09.

use std::cell::Cell;
use std::collections::{BTreeSet, HashSet};
use std::path::Path;

use serde_json::Value;

use crate::model::Module;

// ── error ──────────────────────────────────────────────────────────────────

#[derive(Debug, thiserror::Error)]
pub enum AuditError {
    #[error("not implemented")]
    NotImplemented,
    #[error(transparent)]
    Io(#[from] std::io::Error),
    #[error("json: {0}")]
    Json(#[from] serde_json::Error),
    #[error("probe: {0}")]
    Probe(String),
}

// ── call outcome ───────────────────────────────────────────────────────────

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CallOutcome {
    /// Valid JSON-RPC result ( invocable ).
    Result(Value),
    /// Valid JSON-RPC error object ( invocable per Q3 ).
    Error(Value),
    /// Timeout exceeded.
    Timeout,
    /// Non-JSON / malformed response.
    Malformed,
}

// ── probe trait (sync) ─────────────────────────────────────────────────────

/// Sync transport-independent trait; real rmcp impl in packet-09.
pub trait McpProbe {
    /// Return the set of tool names exposed by the server.
    fn list_tools(&mut self) -> Result<Vec<String>, AuditError>;

    /// Call a single tool with raw JSON args string.
    fn call_tool(&mut self, name: &str, args: &str) -> Result<CallOutcome, AuditError>;
}

// ── report ─────────────────────────────────────────────────────────────────

#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub struct AuditReport {
    pub missing_in_server: Vec<String>,
    pub extra_in_server: Vec<String>,
    pub not_invocable: Vec<String>,
    pub skill_skipped: bool,
}

// ── public API ─────────────────────────────────────────────────────────────

/// Compare declared tools vs server tools; probe invocability.
///
/// RED: returns Err(NotImplemented) so all tests fail until packet-09.
pub fn audit_manifest(
    tools: &[String],
    probe: &mut dyn McpProbe,
    timeout_ms: u64,
) -> Result<AuditReport, AuditError> {
    let _ = (tools, probe, timeout_ms);
    Err(AuditError::NotImplemented)
}

/// Entry point for a single Module.
///
/// RED: stub — returns Err(NotImplemented).
pub fn audit_module(
    _module: &Module,
    _root: &Path,
    _timeout_ms: u64,
) -> Result<AuditReport, AuditError> {
    Err(AuditError::NotImplemented)
}

// ── tests ──────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    // FakeProbe: captures received timeout_ms for test-7.
    struct FakeProbe {
        tools: Vec<String>,
        outcomes: Cell<Option<Vec<CallOutcome>>>,
        received_timeout: Cell<Option<u64>>,
    }

    impl FakeProbe {
        fn new(tools: Vec<String>) -> Self {
            Self {
                tools,
                outcomes: Cell::new(None),
                received_timeout: Cell::new(None),
            }
        }
        fn with_outcomes(mut self, outcomes: Vec<CallOutcome>) -> Self {
            self.outcomes.set(Some(outcomes));
            self
        }
    }

    impl McpProbe for FakeProbe {
        fn list_tools(&mut self) -> Result<Vec<String>, AuditError> {
            Ok(self.tools.clone())
        }
        fn call_tool(&mut self, name: &str, _args: &str) -> Result<CallOutcome, AuditError> {
            // Return next outcome in sequence, or Result("ok") by default.
            if let Some(outcomes) = self.outcomes.get() {
                let idx = outcomes.len().saturating_sub(
                    outcomes.iter()
                        .skip_while(|o| matches!(o, CallOutcome::Result(_) | CallOutcome::Error(_)))
                        .count(),
                );
                // Simple: drain from Vec, fallback to Result
                if let Some(outcome) = outcomes.first() {
                    let copy = outcome.clone();
                    // We can't pop in a Cell, but tests will push one-shot outcomes.
                    // For simplicity, tests will set outcomes with exactly N items.
                    // Each call consumes the first matching non-result item or returns Result.
                    self.outcomes.set(Some(outcomes[1..].to_vec()));
                    Ok(copy)
                } else {
                    // No more planned outcomes → invocable by default
                    Ok(CallOutcome::Result(serde_json::json!("ok")))
                }
            } else {
                // No specific outcomes planned: every call is invocable.
                Ok(CallOutcome::Result(serde_json::json!("ok")))
            }
        }
