    struct FakeProbe {
        tools: Vec<String>,
        outcomes: Cell<Vec<CallOutcome>>,
    }

    impl FakeProbe {
        fn new(tools: Vec<String>) -> Self {
            Self { tools, outcomes: Cell::new(vec![]) }
        }
        fn with_outcomes(mut self, outcomes: Vec<CallOutcome>) -> Self {
            self.outcomes.set(outcomes);
            self
        }
    }

    impl McpProbe for FakeProbe {
        fn list_tools(&mut self) -> Result<Vec<String>, AuditError> {
            Ok(self.tools.clone())
        }
        fn call_tool(&mut self, _name: &str, _args: &str) -> Result<CallOutcome, AuditError> {
            let outcomes = self.outcomes.get();
            if outcomes.is_empty() {
                Ok(CallOutcome::Result(serde_json::json!("ok")))
            } else {
                self.outcomes.set(outcomes[1..].to_vec());
                Ok(outcomes[0].clone())
            }
        }
    }

    // ── test 1: exact match, all invocable ─────────────────────────────────

    #[test]
    fn test1_exact_match_all_invocable() {
