        let report = audit_manifest(&tools, &mut probe, 50);
        assert!(report.is_ok());
        let r = report.unwrap();
        assert_eq!(r.not_invocable, vec![String::from("b"), String::from("c")]);
    }

    // ── test 5: JSON-RPC error object = invocable ──────────────────────────

    #[test]
    fn test5_jsonrpc_error_invocable() {
        let tools: Vec<String> = vec!["a".into(), "b".into()];
        let outcomes = vec![
            CallOutcome::Error(serde_json::json!({"code": -32601, "message": "not found"})),
            CallOutcome::Result(serde_json::json!("ok")),
        ];
        let mut probe = FakeProbe::new(tools.clone()).with_outcomes(outcomes);
