#[cfg(test)]
mod tests {
    use super::*;
    use crate::model::{ModuleKind, Source};
    use std::cell::Cell;

    // ── FakeProbe ──────────────────────────────────────────────────────────

    struct FakeProbe {
        tools: Vec<String>,
        outcomes: Cell<Vec<CallOutcome>>,
    }

    impl FakeProbe {
        fn new(tools: Vec<String>) -> Self {
            Self { tools, outcomes: Cell::new(vec![]) }
        }
        fn with_outcomes(mut self, outcomes: Vec<CallOutcome>) -> Self {
            self.outcomes.set(outcomes);
            self
        }
    }

    impl McpProbe for FakeProbe {
        fn list_tools(&mut self) -> Result<Vec<String>, AuditError> {
            Ok(self.tools.clone())
        }
        fn call_tool(&mut self, _name: &str, _args: &str) -> Result<CallOutcome, AuditError> {
            let outcomes = self.outcomes.get();
            if outcomes.is_empty() {
                Ok(CallOutcome::Result(serde_json::json!("ok")))
            } else {
                self.outcomes.set(outcomes[1..].to_vec());
                Ok(outcomes[0].clone())
            }
        }
    }

    // ── test 1: exact match, all invocable ─────────────────────────────────

    #[test]
    fn test1_exact_match_all_invocable() {
        let tools: Vec<String> = vec!["a".into(), "b".into(), "c".into()];
        let mut probe = FakeProbe::new(tools.clone());
        let report = audit_manifest(&tools, &mut probe, 50);
        assert!(report.is_ok(), "must succeed with exact match");
        let r = report.unwrap();
        assert!(r.missing_in_server.is_empty());
        assert!(r.extra_in_server.is_empty());
        assert!(r.not_invocable.is_empty());
        assert!(!r.skill_skipped);
    }

    // ── test 2: server missing one ─────────────────────────────────────────

    #[test]
    fn test2_server_missing_c() {
        let tools: Vec<String> = vec!["a".into(), "b".into(), "c".into()];
        let mut probe = FakeProbe::new(vec!["a".into(), "b".into()]);
        let report = audit_manifest(&tools, &mut probe, 50);
        assert!(report.is_ok());
        let r = report.unwrap();
        assert_eq!(r.missing_in_server, vec![String::from("c")]);
    }

    // ── test 3: server has extra ───────────────────────────────────────────

    #[test]
    fn test3_server_extra_d() {
        let tools: Vec<String> = vec!["a".into(), "b".into(), "c".into()];
        let mut probe = FakeProbe::new(vec!["a".into(), "b".into(), "c".into(), "d".into()]);
        let report = audit_manifest(&tools, &mut probe, 50);
        assert!(report.is_ok());
        let r = report.unwrap();
        assert_eq!(r.extra_in_server, vec![String::from("d")]);
    }

    // ── test 4: timeout & malformed → not_invocable ────────────────────────

    #[test]
    fn test4_timeout_and_malformed() {
        let tools: Vec<String> = vec!["a".into(), "b".into(), "c".into()];
        let outcomes = vec![
            CallOutcome::Result(serde_json::json!("ok")),
            CallOutcome::Malformed,
            CallOutcome::Timeout,
        ];
        let mut probe = FakeProbe::new(tools.clone()).with_outcomes(outcomes);
        let report = audit_manifest(&tools, &mut probe, 50);
        assert!(report.is_ok());
        let r = report.unwrap();
        assert_eq!(r.not_invocable, vec![String::from("b"), String::from("c")]);
    }

    // ── test 5: JSON-RPC error object = invocable ──────────────────────────

    #[test]
    fn test5_jsonrpc_error_invocable() {
        let tools: Vec<String> = vec!["a".into(), "b".into()];
        let outcomes = vec![
            CallOutcome::Error(serde_json::json!({"code": -32601, "message": "not found"})),
            CallOutcome::Result(serde_json::json!("ok")),
        ];
        let mut probe = FakeProbe::new(tools.clone()).with_outcomes(outcomes);
        let report = audit_manifest(&tools, &mut probe, 50);
        assert!(report.is_ok());
        let r = report.unwrap();
        assert!(!r.not_invocable.contains(&String::from("a")));
        assert!(r.not_invocable.is_empty());
    }

    // ── test 6: kind=skill → skipped ───────────────────────────────────────

    #[test]
    fn test6_skill_skipped() {
        let module = Module {
            kind: ModuleKind::Skill,
            autoload: true,
            risk: None,
            source: Source::Git {
                git: "https://example.com/x".into(),
                rev: "v1".into(),
            },
            command: None,
            tools: vec![],
            context_cost_tokens: 0,
            update: None,
        };
        let report = audit_module(&module, Path::new("/"), 50);
        assert!(report.is_ok());
        let r = report.unwrap();
        assert!(r.skill_skipped);
    }

    // ── test 7: timeout_ms propagated ─────────────────────────────────────

    #[test]
    fn test7_timeout_propagated() {
        let tools: Vec<String> = vec!["a".into()];
        let mut probe = FakeProbe::new(tools.clone());
        let report = audit_manifest(&tools, &mut probe, 50);
        assert!(report.is_ok());
        let r = report.unwrap();
        assert!(r.missing_in_server.is_empty());
    }

    // ── test 8: empty manifest + empty server = vacuous pass ──────────────

    #[test]
    fn test8_vacuous_pass() {
        let tools: Vec<String> = vec![];
        let mut probe = FakeProbe::new(vec![]);
        let report = audit_manifest(&tools, &mut probe, 50);
        assert!(report.is_ok());
        let r = report.unwrap();
        assert!(r.missing_in_server.is_empty());
        assert!(r.extra_in_server.is_empty());
        assert!(r.not_invocable.is_empty());
    }
}

