    fn test7_timeout_propagated() {
        let tools = vec!["a".into()];
        let mut probe = FakeProbe::new(tools);
        let report = audit_manifest(&tools, &mut probe, 50);
        // Once implemented, 50 ms is used for the per-tool timeout.
        assert!(report.is_ok());
        let r = report.unwrap();
        assert!(r.missing_in_server.is_empty());
    }

    // ── test 8: empty manifest + empty server = vacuous pass ──────────────

    #[test]
    fn test8_vacuous_pass() {
