use std::collections::BTreeMap;
use std::path::Path;

use serde::{Deserialize, Serialize};

// ── error ──────────────────────────────────────────────────────────────────

#[derive(Debug, thiserror::Error)]
pub enum ModelError {
    #[error("not implemented")]
    NotImplemented,
    #[error(transparent)]
    Toml(#[from] toml::de::Error),
    #[error(transparent)]
    Io(#[from] std::io::Error),
}

// ── calibration ────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Calibration {
    #[serde(rename = "tokens_per_byte", alias = "bytes_per_token", default)]
    pub tokens_per_byte: f64,
    pub measured_at: String,
}

// ── module kind ────────────────────────────────────────────────────────────

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
pub enum ModuleKind {
    Mcp,
    Skill,
}

// ── source ─────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(untagged)]
pub enum Source {
    Git {
        git: String,
        rev: String,
    },
    Npm {
        npm: String,
        version: Option<String>,
    },
    Crate {
        #[serde(rename = "cargo")]
        krate: String,
        version: Option<String>,
    },
}

// ── update policy ──────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UpdatePolicy {
    pub channel: String,
    pub policy: String,
}

// ── module ─────────────────────────────────────────────────────────────────

#[derive(Debug, Clone, Serialize, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Module {
    pub kind: ModuleKind,
    #[serde(default = "default_bool_true")]
    pub autoload: bool,
    pub risk: Option<String>,
    pub source: Source,
    pub command: Option<String>,
    #[serde(default)]
    pub tools: Vec<String>,
    #[serde(default)]
    pub context_cost_tokens: u64,
    pub update: Option<UpdatePolicy>,
}

fn default_bool_true() -> bool {
    true
}

// ── registry / modules file ───────────────────────────────────────────────

#[derive(Debug, Serialize, Deserialize)]
pub struct Registry {
    pub budgets: Option<u64>,
    pub calibration: Calibration,
}

#[derive(Debug, Serialize, Deserialize)]
pub struct ModulesFile {
    pub registry: Registry,
    pub module: BTreeMap<String, Module>,
}

impl ModulesFile {
    /// Parse TOML.
    pub fn from_toml_str(s: &str) -> Result<Self, ModelError> {
        Ok(toml::from_str(s)?)
    }

    /// Read from filesystem.
    pub fn load(path: &Path) -> Result<Self, ModelError> {
        let s = std::fs::read_to_string(path)?;
        Self::from_toml_str(&s)
    }
}

// ── formula ────────────────────────────────────────────────────────────────

/// tokens = round(bytes * tokens_per_byte)
pub fn tokens_for(bytes: u64, tokens_per_byte: f64) -> u64 {
    (bytes as f64 * tokens_per_byte).round() as u64
}

