        let c = cli.unwrap();
        match &c.command {
            Command::Module { command } => match command {
                ModuleCommand::Update(a) => {
                    assert!(a.name.is_none());
                }
                _ => panic!("expected Update"),
            },
        }
    }

    #[test]
    fn run_badcmd_exit2() {
        let code = run(vec!["stellwerk".into(), "badcmd".into()]);
        assert_eq!(code, 2);
    }

    #[test]
    fn run_module_no_subcmd_exit2() {
        let code = run(vec!["stellwerk".into(), "module".into()]);
        assert_eq!(code, 2);
    }

    #[test]
    fn run_help_exit0() {
        let code = run(vec!["stellwerk".into(), "--help".into()]);
        assert_eq!(code, 0);
    }

    #[test]
    fn run_module_add_placeholder_exit1() {
        let code = run(vec![
            "stellwerk".into(),
            "module".into(),
            "add".into(),
            "polyforge".into(),
            "--kind".into(),
            "mcp".into(),
            "--git".into(),
            "https://e/x".into(),
            "--rev".into(),
            "abc".into(),
        ]);
        assert_eq!(code, 1);
    }
}

