//! Audit shims — packet-08 (RED).
//!
//! Trait-шов McpProbe + заглушки; реальный rmcp spawn — packet-09.

use std::cell::Cell;
use std::collections::{BTreeSet, HashSet};
use std::path::Path;

use serde_json::Value;

use crate::model::Module;

// ── error ──────────────────────────────────────────────────────────────────

#[derive(Debug, thiserror::Error)]
pub enum AuditError {
    #[error("not implemented")]
    NotImplemented,
    #[error(transparent)]
    Io(#[from] std::io::Error),
    #[error("json: {0}")]
    Json(#[from] serde_json::Error),
    #[error("probe: {0}")]
    Probe(String),
}

// ── call outcome ───────────────────────────────────────────────────────────

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum CallOutcome {
    /// Valid JSON-RPC result ( invocable ).
    Result(Value),
    /// Valid JSON-RPC error object ( invocable per Q3 ).
    Error(Value),
    /// Timeout exceeded.
    Timeout,
    /// Non-JSON / malformed response.
    Malformed,
}

// ── probe trait (sync) ─────────────────────────────────────────────────────

/// Sync transport-independent trait; real rmcp impl in packet-09.
pub trait McpProbe {
    /// Return the set of tool names exposed by the server.
    fn list_tools(&mut self) -> Result<Vec<String>, AuditError>;

    /// Call a single tool with raw JSON args string.
    fn call_tool(&mut self, name: &str, args: &str) -> Result<CallOutcome, AuditError>;
}

// ── report ─────────────────────────────────────────────────────────────────

#[derive(Debug, Default, Clone, PartialEq, Eq)]
pub struct AuditReport {
    pub missing_in_server: Vec<String>,
    pub extra_in_server: Vec<String>,
    pub not_invocable: Vec<String>,
    pub skill_skipped: bool,
}

// ── public API ─────────────────────────────────────────────────────────────

/// Compare declared tools vs server tools; probe invocability.
///
/// RED: returns Err(NotImplemented) so all tests fail until packet-09.
pub fn audit_manifest(
    tools: &[String],
    probe: &mut dyn McpProbe,
    timeout_ms: u64,
) -> Result<AuditReport, AuditError> {
    let _ = (tools, probe, timeout_ms);
    Err(AuditError::NotImplemented)
}

/// Entry point for a single Module.
///
/// RED: stub — returns Err(NotImplemented).
pub fn audit_module(
    _module: &Module,
    _root: &Path,
    _timeout_ms: u64,
) -> Result<AuditReport, AuditError> {
    Err(AuditError::NotImplemented)
}

// ── tests ──────────────────────────────────────────────────────────────────

#[cfg(test)]
mod tests {
    use super::*;

    // FakeProbe: captures received timeout_ms for test-7.
    struct FakeProbe {
        tools: Vec<String>,
        outcomes: Cell<Option<Vec<CallOutcome>>>,
        received_timeout: Cell<Option<u64>>,
    }

    impl FakeProbe {
        fn new(tools: Vec<String>) -> Self {
            Self {
                tools,
                outcomes: Cell::new(None),
                received_timeout: Cell::new(None),
            }
        }
        fn with_outcomes(mut self, outcomes: Vec<CallOutcome>) -> Self {
            self.outcomes.set(Some(outcomes));
            self
        }
    }

    impl McpProbe for FakeProbe {
        fn list_tools(&mut self) -> Result<Vec<String>, AuditError> {
            Ok(self.tools.clone())
        }
        fn call_tool(&mut self, name: &str, _args: &str) -> Result<CallOutcome, AuditError> {
            // Return next outcome in sequence, or Result("ok") by default.
            if let Some(outcomes) = self.outcomes.get() {
                let idx = outcomes.len().saturating_sub(
                    outcomes.iter()
                        .skip_while(|o| matches!(o, CallOutcome::Result(_) | CallOutcome::Error(_)))
                        .count(),
                );
                // Simple: drain from Vec, fallback to Result
                if let Some(outcome) = outcomes.first() {
                    let copy = outcome.clone();
                    // We can't pop in a Cell, but tests will push one-shot outcomes.
                    // For simplicity, tests will set outcomes with exactly N items.
                    // Each call consumes the first matching non-result item or returns Result.
                    self.outcomes.set(Some(outcomes[1..].to_vec()));
                    Ok(copy)
                } else {
                    // No more planned outcomes → invocable by default
                    Ok(CallOutcome::Result(serde_json::json!("ok")))
                }
            } else {
                // No specific outcomes planned: every call is invocable.
                Ok(CallOutcome::Result(serde_json::json!("ok")))
            }
        }
    }

    // ── test 1: exact match, all invocable ─────────────────────────────────

    #[test]
    #[ignore] // RED: Err(NotImplemented)
    fn test1_exact_match_all_invocable() {
        let tools = vec!["a".into(), "b".into(), "c".into()];
        let mut probe = FakeProbe::new(tools.clone());
        let report = audit_manifest(&tools, &mut probe, 50);
        assert!(report.is_ok(), "must succeed with exact match");
        let r = report.unwrap();
        assert!(r.missing_in_server.is_empty());
        assert!(r.extra_in_server.is_empty());
        assert!(r.not_invocable.is_empty());
        assert!(!r.skill_skipped);
    }

    // ── test 2: server missing one ─────────────────────────────────────────

    #[test]
    #[ignore] // RED: Err(NotImplemented)
    fn test2_server_missing_c() {
        let tools = vec!["a".into(), "b".into(), "c".into()];
        let mut probe = FakeProbe::new(vec!["a".into(), "b".into()]);
        let report = audit_manifest(&tools, &mut probe, 50);
        assert!(report.is_ok());
        let r = report.unwrap();
        assert_eq!(r.missing_in_server, vec!["c".into()]);
    }

    // ── test 3: server has extra ───────────────────────────────────────────

    #[test]
    #[ignore] // RED: Err(NotImplemented)
    fn test3_server_extra_d() {
        let tools = vec!["a".into(), "b".into(), "c".into()];
        let mut probe = FakeProbe::new(vec!["a".into(), "b".into(), "c".into(), "d".into()]);
        let report = audit_manifest(&tools, &mut probe, 50);
        assert!(report.is_ok());
        let r = report.unwrap();
        assert_eq!(r.extra_in_server, vec!["d".into()]);
    }

    // ── test 4: timeout & malformed → not_invocable ────────────────────────

    #[test]
    #[ignore] // RED: Err(NotImplemented)
    fn test4_timeout_and_malformed() {
        let tools = vec!["a".into(), "b".into(), "c".into()];
        let outcomes = vec![
            CallOutcome::Result(serde_json::json!("ok")), // a → ok
            CallOutcome::Malformed,                        // b → malformed
            CallOutcome::Timeout,                          // c → timeout
        ];
        let mut probe = FakeProbe::new(tools.clone()).with_outcomes(outcomes);
        let report = audit_manifest(&tools, &mut probe, 50);
        assert!(report.is_ok());
        let r = report.unwrap();
        assert_eq!(r.not_invocable, vec!["b".into(), "c".into()]);
    }

    // ── test 5: JSON-RPC error object = invocable ──────────────────────────

    #[test]
    #[ignore] // RED: Err(NotImplemented)
    fn test5_jsonrpc_error_invocable() {
        let tools = vec!["a".into(), "b".into()];
        let outcomes = vec![
            CallOutcome::Error(serde_json::json!({"code": -32601, "message": "not found"})),
            CallOutcome::Result(serde_json::json!("ok")),
        ];
        let mut probe = FakeProbe::new(tools).with_outcomes(outcomes);
        let report = audit_manifest(&tools, &mut probe, 50);
        assert!(report.is_ok());
        let r = report.unwrap();
        assert!(!r.not_invocable.contains(&"a".into()));
        assert_eq!(r.not_invocable, Vec::<String>::new());
    }

    // ── test 6: kind=skill → skipped ───────────────────────────────────────

    #[test]
    #[ignore] // RED: Err(NotImplemented)
    fn test6_skill_skipped() {
        let module = Module {
            kind: ModuleKind::Skill,
            autoload: true,
            risk: None,
            source: Source::Git {
                git: "https://example.com/x".into(),
                rev: "v1".into(),
            },
            command: None,
            tools: vec![],
            context_cost_tokens: 0,
            update: None,
        };
        let report = audit_module(&module, Path::new("/"), 50);
        assert!(report.is_ok());
        let r = report.unwrap();
        assert!(r.skill_skipped);
    }

    // ── test 7: timeout_ms propagated ─────────────────────────────────────

    #[test]
    #[ignore] // RED: Err(NotImplemented)
    fn test7_timeout_propagated() {
        let tools = vec!["a".into()];
        // Probe that records timeout_ms — requires McpProbe to expose it.
        // We test via FakeProbe that stores received_timeout.
        // Stub probe stores it; audit_manifest must pass it through.
        let mut probe = FakeProbe::new(tools);
        // The real test needs McpProbe to receive timeout_ms.
        // For RED, we assert the function signature accepts it.
        let _ = audit_manifest(&tools, &mut probe, 50);
        // Once implemented, 50 ms is used for the per-tool timeout.
    }

    // ── test 8: empty manifest + empty server = vacuous pass ──────────────

    #[test]
    #[ignore] // RED: Err(NotImplemented)
    fn test8_vacuous_pass() {
        let tools: Vec<String> = vec![];
        let mut probe = FakeProbe::new(vec![]);
        let report = audit_manifest(&tools, &mut probe, 50);
        assert!(report.is_ok());
        let r = report.unwrap();
        assert!(r.missing_in_server.is_empty());
        assert!(r.extra_in_server.is_empty());
        assert!(r.not_invocable.is_empty());
    }

    // ── RED smoke: without #[ignore] these still fail on Err ──────────────

    #[test]
    fn red_smoke_impl_not_yet() {
        let mut probe = FakeProbe::new(vec!["a".into()]);
        let res = audit_manifest(&["a".into()], &mut probe, 50);
        assert!(res.is_err(), "RED: implementation not yet present");
        assert!(matches!(res.unwrap_err(), AuditError::NotImplemented));
    }
}

