edits.newText:
struct FakeProbe {
    tools: Vec<String>,
    outcomes: Vec<CallOutcome>,
    idx: Cell<usize>,
}

impl FakeProbe {
    fn new(tools: Vec<String>) -> Self {
        Self { tools, outcomes: vec![], idx: Cell::new(0) }
    }
    fn with_outcomes(self, outcomes: Vec<CallOutcome>) -> Self {
        Self { outcomes, ..self }
    }
}

impl McpProbe for FakeProbe {
    fn list_tools(&mut self) -> Result<Vec<String>, AuditError> {
        Ok(self.tools.clone())
    }
    fn call_tool(&mut self, _name: &str, _args: &str) -> Result<CallOutcome, AuditError> {
        let i = self.idx.get();
        if i >= self.outcomes.len() {
            Ok(CallOutcome::Result(serde_json::json!("ok")))
        } else {
            let outcome = self.outcomes[i].clone();
            self.idx.set(i + 1);
            Ok(outcome)
        }
    }
}

